    aboutScheduleTitle: 'زمان‌بندی به‌روزرسانی داده‌ها',
    aboutScheduleBody:
      'یک فرایند زمان‌بندی‌شده هر روز ساعت ۰۴:۲۰ به وقت هماهنگ جهانی (UTC) همه منابع را به‌روزرسانی می‌کند و نسخه‌ای از پیش محاسبه‌شده از داده‌ها را ذخیره می‌کند. صفحه‌ای که مشاهده می‌کنید همین نسخه ذخیره‌شده را نمایش می‌دهد. داده‌های روزانه هر روز و داده‌های ماهانه و فصلی هم‌زمان با انتشار رسمی ناشر مربوطه به‌روز می‌شوند. داده‌های بازارهای سهام جهان طبق برنامه‌ای جداگانه، در شامگاه روزهای کاری و ساعت ۲۳:۳۰ به وقت UTC به‌روزرسانی می‌شوند.',
